'use strict';
const StudioExtraMissions=(()=>{
 const core=StudioMissionCore,esc=senEscape;
 const svg=b=>'<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 600 360" aria-hidden="true">'+b+'</svg>';
 function roomArt(s){const t=core.task(s),outdoors=t.room==='Picnic shelter';let b='<rect width="600" height="360" rx="24" fill="'+(outdoors?'#e5f0ed':t.room==='Bedroom'?'#eee9f2':'#f1eee2')+'"/><path d="M0 300H600V360H0Z" fill="'+(outdoors?'#cbdcae':'#dfc9a4')+'"/>';
  if(outdoors)b+='<circle cx="525" cy="48" r="21" fill="#e5c46f"/><path d="M0 115Q140 52 290 111T600 100V360H0Z" fill="#adc99e"/><path d="M18 112L66 29L111 112Z" fill="#d8b678" stroke="#8e7957" stroke-width="3"/><path d="M50 112L66 75L82 112Z" fill="#8b9079"/>';
  else b+='<rect x="260" y="22" width="80" height="60" rx="4" fill="#d7e9ec" stroke="#a9b8b0" stroke-width="6"/><path d="M300 22V82M260 52H340" stroke="#a9b8b0" stroke-width="4"/>';
  if(t.room==='Kitchen')b+='<rect x="22" y="210" width="88" height="90" rx="4" fill="#a3b5b2" stroke="#6c8178" stroke-width="3"/><circle cx="44" cy="225" r="7" fill="#586d65"/><circle cx="82" cy="225" r="7" fill="#586d65"/><rect x="32" y="246" width="65" height="40" rx="4" fill="#6c8178"/><path d="M40 254H88" stroke="#dce8df" stroke-width="4"/>';
  if(t.room==='Bedroom')b+='<path d="M445 260H580V288H445Z" fill="#b59fc5"/><rect x="530" y="245" width="39" height="17" rx="7" fill="#fffdf7"/><path d="M446 288V300M580 230V300" stroke="#86694e" stroke-width="6"/>';
  if(t.room==='Hallway')b+='<path d="M453 45H555M468 45V67M505 45V67M543 45V67" stroke="#9b7957" stroke-width="6" stroke-linecap="round"/>';
  [100,340].forEach((x,i)=>{b+='<rect x="'+x+'" y="110" width="160" height="190" rx="8" fill="#7b765e" stroke="#927855" stroke-width="5"/><path d="M'+(x+8)+' 290H'+(x+152)+'" stroke="#c7ac79" stroke-width="9"/>';if(s.opened.includes(i)){const edge=i===0?x-19:x+160;b+='<path d="M'+edge+' 100L'+(edge+19)+' 110V300L'+edge+' 311Z" fill="#d1b785" stroke="#927855" stroke-width="3"/>';}else b+='<rect x="'+x+'" y="110" width="160" height="190" rx="7" fill="'+(outdoors?'#c9a676':'#d8c7a4')+'" stroke="#927855" stroke-width="5"/><circle cx="'+(x+135)+'" cy="207" r="7" fill="#9d7950"/>';});return svg(b);
 }
 function lockerArt(){return svg('<rect width="600" height="360" rx="24" fill="#edf2e8"/><path d="M0 315H600V360H0Z" fill="#d7c8aa"/><g stroke="#778c7b" stroke-width="5"><rect x="95" y="45" width="170" height="270" rx="12" fill="#d2e0d1"/><rect x="335" y="45" width="170" height="270" rx="12" fill="#dce2ee"/><path d="M105 295H255M345 295H495"/></g><path d="M116 62H244M356 62H484" stroke="#9aaf9a" stroke-width="4"/><path d="M115 78H244M355 78H484" stroke="#9aaf9a" stroke-width="4"/>');}
 function itemArt(phrase){return wordQuestPaintArt(phrase,phrase.startsWith('red')?'#b8493e':'#b88b5b');}
 function body(s){const t=core.task(s);if(s.mode==='rooms'){return '<p class="extra-room-title">'+esc(t.room)+'</p><div class="extra-room-board">'+roomArt(s)+[0,1].map(i=>'<button data-mission-door="'+i+'" class="extra-door '+(s.opened.includes(i)?'is-open':'')+'" style="left:'+(i===0?30:70)+'%" aria-label="'+(s.opened.includes(i)?'Close':'Open')+' compartment '+(i+1)+'" aria-expanded="'+s.opened.includes(i)+'">'+(s.opened.includes(i)?'↶':'')+'</button>'+(s.opened.includes(i)&&!(s.done&&t.items[i]===t.target)?'<button data-mission-room-item="'+t.items[i]+'" class="extra-room-object" style="left:'+(i===0?30:70)+'%" aria-label="Picture: '+esc(t.items[i])+'" aria-pressed="'+(s.selected===t.items[i])+'">'+readingPicture(t.items[i])+'</button>':'')).join('')+'<button id="missionDoorHandle" class="extra-door-handle" aria-label="Open the dragged door here">Open</button></div><button id="missionRoomTray" class="extra-room-tray" aria-label="Put selected object picture on the tray">'+(s.done?readingPicture(t.target):'<span>Collection tray ＋</span>')+'</button><p class="mission-how">Open a compartment, then retrieve the requested picture. Drag a door to Open, or tap it. Drag the picture to the tray, or select and place.</p><button id="missionExtraModel" class="back">'+(s.modelVisible?'Hide the picture model':'Show the picture model')+'</button>'+(s.modelVisible?'<div class="extra-target-model">'+readingPicture(t.target)+'</div>':'');}
  if(s.mode==='claims')return '<div class="extra-lockers"><div class="extra-locker-art" aria-hidden="true">'+lockerArt()+'</div>'+t.tickets.map((ticket,i)=>'<button data-mission-locker="'+i+'" class="extra-locker" aria-label="Return an object to locker labelled '+ticket+'"><span class="extra-claim-label">'+ticket.split(' ').map(wordPlayPaint).join(' ')+'</span><span class="extra-locker-picture">'+(s.returned[i]?itemArt(s.returned[i]):'<span aria-hidden="true">＋</span>')+'</span></button>').join('')+'</div><div class="extra-property-desk">'+t.items.filter(x=>!Object.values(s.returned).includes(x)).map(x=>'<button class="extra-property" data-mission-property="'+x+'" aria-label="Picture: '+x+'" aria-pressed="'+(s.selected===x)+'">'+itemArt(x)+(s.showNames?'<span>'+x.split(' ').map(wordPlayPaint).join(' ')+'</span>':'')+'</button>').join('')+'</div><p class="mission-how">Read both words on each locker. Return the matching picture card by dragging, or select a card then its locker. Returned cards stay inside.</p><button id="missionItemNames" class="back">'+(s.showNames?'Hide':'Show')+' item names</button>';return null;
 }
 function prompt(s){return s.mode==='rooms'?'Find the '+core.task(s).target+' for the collection tray.':s.mode==='claims'?'Read the locker labels. Return both matching pictures.':null;}
 function bind({state:s,act,clicks,drag}){if(s.mode==='rooms'){
  clicks('[data-mission-door]',el=>act({type:'door',value:+el.dataset.missionDoor}));drag('[data-mission-door]','#missionDoorHandle',el=>{const i=+el.dataset.missionDoor;if(!s.opened.includes(i))act({type:'door',value:i});});clicks('[data-mission-room-item]',el=>act({type:'select',value:el.dataset.missionRoomItem}));clicks('#missionRoomTray',()=>{if(s.selected)act({type:'retrieve',value:s.selected});else act({type:'hint',value:'Open a compartment, then choose a picture to retrieve.'});});drag('[data-mission-room-item]','#missionRoomTray',el=>act({type:'retrieve',value:el.dataset.missionRoomItem}));clicks('#missionExtraModel',()=>act({type:'model'}));
 }if(s.mode==='claims'){clicks('[data-mission-property]',el=>act({type:'select',value:el.dataset.missionProperty}));clicks('[data-mission-locker]',el=>{if(s.selected)act({type:'return',value:s.selected,owner:+el.dataset.missionLocker});else act({type:'hint',value:'Choose a picture card, then its labelled locker.'});});drag('[data-mission-property]','[data-mission-locker]',(el,t)=>act({type:'return',value:el.dataset.missionProperty,owner:+t.dataset.missionLocker}));clicks('#missionItemNames',()=>act({type:'names'}));}}
 return{body,prompt,bind,roomArt,lockerArt,cover:key=>key==='rooms'?roomArt(core.create('rooms')):key==='claims'?lockerArt():null};
})();
